# Verify difference set property
D = [0, 1, 4, 6]
v = 13

diffs = {}
for a in D:
    for b in D:
        if a != b:
            d = (a - b) % v
            diffs.setdefault(d, []).append((a,b))

print("Differences:")
for d in sorted(diffs.keys()):
    print(f"  {d}: {diffs[d]}")

# Check each nonzero difference appears exactly once
for d in range(1, v):
    if d not in diffs:
        print(f"Missing diff {d}")
    elif len(diffs[d]) != 1:
        print(f"Diff {d} appears {len(diffs[d])} times")
    else:
        print(f"Diff {d}: OK")
